{
  "findings": [
    {
      "ref": "[D539]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child in multiplayer servers.",
      "stance": "risk",
      "quote": "Chat on those servers is where most of the risk lives. Both versions let players block, mute or report someone from the pause menu, and Java Edition has a Player Reporting tool that sends abusive chat to Minecraft’s moderators, including from private servers.[[4]](#sources)[[7]](#sources)"
    },
    {
      "ref": "[D539]",
      "area": "money",
      "claim": "The app pushes in-app purchases through the Marketplace using Minecoins.",
      "stance": "risk",
      "quote": "Bedrock Edition’s Marketplace sells maps, skins and mini-games for Minecoins, an in-game currency bought with real money.[[2]](#sources)"
    },
    {
      "ref": "[D539]",
      "area": "data",
      "claim": "The app collects user data and may share it with third parties for ads or other purposes.",
      "stance": "neutral",
      "quote": "The ESRB rates Minecraft E10+ for Fantasy Violence, and adds Users Interact and In-Game Purchases.[[1]](#sources)"
    },
    {
      "ref": "[D539]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, as the app treats accounts under 16 as child accounts that a parent manages.",
      "stance": "mitigation",
      "quote": "In the US and EU, Minecraft treats every account for someone under 16 as a child account that a parent manages.[[4]](#sources)"
    },
    {
      "ref": "[D539]",
      "area": "content",
      "claim": "A parent reports that the game contains mild cartoonish violence with no blood and respawn mechanics.",
      "stance": "neutral",
      "quote": "Violence is mild and cartoonish. Players fight monsters such as zombies and skeletons with swords, axes and bows. They can also hurt animals and villagers, though the game doesn’t encourage it.[[1]](#sources)"
    },
    {
      "ref": "[D539]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has faced fines, breaches, lawsuits or regulatory actions related to data or safety.",
      "stance": "risk",
      "quote": "Microsoft, which owns Minecraft, has started asking some account holders to verify their age. Its age assurance FAQ says users in the United Kingdom, Australia, Brazil and Singapore can verify now, with a selfie-based age estimate, an ID document or a government login.[[10]](#sources)"
    }
  ]
}
